const PURIFY_NEGATIVE_KEYS = new Set([
  'poison', 'poisoned', 'burn', 'burning', 'bleed', 'bleeding',
  'stun', 'stunned', 'stagger', 'staggered', 'curse', 'cursed',
  'weaken', 'weakened', 'confuse', 'confused', 'shock', 'shocked',
