import { ActiveEffects } from "../components/ActiveEffects.js";
import { CombatPosture, COMBAT_POSTURES } from "../components/CombatPosture.js";
import { Equipment } from "../components/Equipment.js";
import { ItemInfo } from "../components/ItemInfo.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Stamina } from "../components/Stamina.js";
import { STAMINA_REGEN_COOLDOWN } from "../data/regenConstants.js";
import { toInt } from "./numberCoerce.js";
import { Duration } from "../components/Duration.js";
import { StatusEffectNode } from "../components/StatusEffectNode.js";
import { descendantsWith } from "./topology.js";

export const SHIELD_GUARD_KEY = "shield_guard";
export const SHIELD_BROKEN_KEY = "shield_broken";
export const DIVINE_SHIELD_KEY = "divine_shield";
export const SHIELD_MAX_GUARD_STACKS = 2;

function isActiveTimedEffect(effect) {
  if (!effect || typeof effect !== "object") return false;
  if (toInt(effect.onsetLeft, 0) > 0) return false;
  return toInt(effect.turnsLeft, 0) > 0;
}

/**
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} entityId
 */
export function hasEquippedShield(world, entityId) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0) || !world?.isAlive?.(id)) return false;
  const eq = world.get(id, Equipment);
  const offhandId = Number(eq?.offhand || 0) | 0;
  if (!(offhandId > 0) || !world.isAlive(offhandId)) return false;
  const info = world.get(offhandId, ItemInfo);
  if (!info) return false;
  const slot = String(info.slot || "").toLowerCase();
  const subtype = String(info.subtype || "").toLowerCase();
  const identity = String(world.get(offhandId, NamedIdentity)?.identity || "").toLowerCase();
  const name = String(world.get(offhandId, NamedIdentity)?.name || "").toLowerCase();
  if (subtype === "shield") return true;
  if (slot === "offhand" && !info.damageDice) {
    if (identity.includes("shield") || name.includes("shield")) return true;
  }
  return false;
}

/**
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} entityId
 */
export function ensureShieldGuardState(world, entityId) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0) || !world?.isAlive?.(id)) return null;
  let ae = world.get(id, ActiveEffects);
  if (!ae || !Array.isArray(ae.effects)) {
    try { world.add(id, ActiveEffects, { effects: [] }); } catch {}
    ae = world.get(id, ActiveEffects);
  }
  if (!ae || !Array.isArray(ae.effects)) return null;
  return ae;
}

/**
 * @param {Array<any>} effects
 * @param {string} key
 */
function findEffect(effects, key) {
  for (let i = 0; i < effects.length; i++) {
    const e = effects[i];
    if (!e || String(e.key || "") !== key) continue;
    if (!isActiveTimedEffect(e)) continue;
    return e;
  }
  return null;
}

function findActiveBreakableGuard(effects) {
  for (let i = 0; i < effects.length; i++) {
    const effect = effects[i];
    if (!effect || !effect.meta || effect.meta.maxGuardStacks == null) continue;
    if (!isActiveTimedEffect(effect)) continue;
    const meta = effect.meta && typeof effect.meta === "object" ? effect.meta : null;
    if (toInt(meta?.guardBrokenTurns, 0) > 0) continue;
    if (toInt(meta?.guardStacks, 0) <= 0) continue;
    return effect;
  }
  return null;
}

function findTopologyDivineShield(world, entityId) {
  for (const [nodeId, node] of descendantsWith(world, entityId, StatusEffectNode)) {
    if (String(node?.key || "") !== DIVINE_SHIELD_KEY) continue;
    const duration = world.get(nodeId, Duration);
    if (!isActiveTimedEffect({ turnsLeft: duration?.turnsLeft, onsetLeft: duration?.onsetLeft })) continue;
    if (!node?.meta || node.meta.maxGuardStacks == null) continue;
    if (toInt(node.meta.guardBrokenTurns, 0) > 0) continue;
    if (toInt(node.meta.guardStacks, 0) <= 0) continue;
    return { ...node, turnsLeft: duration.turnsLeft };
  }
  return null;
}

/**
 * @param {Array<any>} effects
 * @param {string} key
 */
function removeEffect(effects, key) {
  for (let i = effects.length - 1; i >= 0; i--) {
    const e = effects[i];
    if (!e || String(e.key || "") !== key) continue;
    effects.splice(i, 1);
  }
}

/**
 * Ensure equipped-shield defenders expose a guard icon/state unless broken.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} entityId
 */
export function refreshShieldGuard(world, entityId) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0) || !world?.isAlive?.(id)) return;
  const ae = ensureShieldGuardState(world, id);
  if (!ae) return;
  const effects = ae.effects;
  const broken = findEffect(effects, SHIELD_BROKEN_KEY);
  const posture = world.get(id, CombatPosture);
  const stance = String(posture?.stance || "").toLowerCase();
  if (!hasEquippedShield(world, id) || stance !== COMBAT_POSTURES.guarded) {
    removeEffect(effects, SHIELD_GUARD_KEY);
    removeEffect(effects, SHIELD_BROKEN_KEY);
    return;
  }
  if (broken) {
    removeEffect(effects, SHIELD_GUARD_KEY);
    return;
  }
  let guard = findEffect(effects, SHIELD_GUARD_KEY);
  if (!guard) {
    guard = {
      key: SHIELD_GUARD_KEY,
      turnsLeft: 2,
      potency: 1,
      stacks: SHIELD_MAX_GUARD_STACKS,
      meta: { maxStacks: SHIELD_MAX_GUARD_STACKS },
    };
    effects.push(guard);
    return;
  }
  guard.turnsLeft = Math.max(2, toInt(guard.turnsLeft, 0));
  runSpellScript(world, caster, SPELL_DEFS.purify, {});

  assertEquals(events[0].removed, 0);
  assertEquals(effectKeys(world, caster).length, 1);
});

// ─── Divine Shield ──────────────────────────────────────────────────────────

Deno.test("divine_shield applies one authored breakable ward", () => {
  const world = makeWorld();
  const caster = makeCaster(world, 5, 5);

  runSpellScript(world, caster, SPELL_DEFS.divine_shield, {});

  const keys = effectKeys(world, caster);
  assert(keys.includes('divine_shield'), 'should apply divine_shield');
  assertEquals(keys.length, 1, 'divine_shield should not fan out into status rows');

  const ae = world.get(caster, ActiveEffects);
  const ward = ae.effects.find((e) => e?.key === 'divine_shield');
  assertEquals(ward.turnsLeft, 20);
  assertEquals(ward.potency, 3, 'divine_shield ward should retain its hardening potency');
  assertEquals(ward.meta.guardStacks, 2, 'divine_shield should start with two guard stacks');
});

Deno.test("divine_shield reads guard mechanics from the spell definition", () => {
  const world = makeWorld();
  const caster = makeCaster(world);
  runSpellScript(world, caster, {
    ...SPELL_DEFS.divine_shield,
    activeEffect: {
      duration: 9,
      potency: 6,
      stacks: 1,
      mechanics: { guardStacks: 4, maxGuardStacks: 4, blessed: false },
    },
  }, {});

  const ward = world.get(caster, ActiveEffects).effects.find((e) => e?.key === "divine_shield");
  assertEquals(ward.turnsLeft, 9);
  assertEquals(ward.potency, 6);
  assertEquals(ward.meta.guardStacks, 4);
  assertEquals(ward.meta.maxGuardStacks, 4);
  assertEquals(ward.meta.blessed, false);
});

Deno.test("divine_shield guard is breakable without creating shield status rows", () => {
  const world = makeWorld();
  const caster = makeCaster(world, 5, 5);
  const attacker = makeEnemy(world, 5, 4);
  world.add(caster, Facing, { dx: 0, dy: -1 });
  runSpellScript(world, caster, SPELL_DEFS.divine_shield, {});

  const before = world.get(caster, Vitality).hp;
  dealDamage(world, { target: caster, source: attacker, amount: 10, type: 'physical', cause: 'test' });
  const ward = world.get(caster, ActiveEffects).effects.find((e) => e?.key === 'divine_shield');
  assertEquals(world.get(caster, Vitality).hp, before - 8, 'front hit should be mitigated by the ward');
  assertEquals(ward.meta.guardStacks, 1);

  dealDamage(world, { target: caster, source: attacker, amount: 10, type: 'physical', cause: 'test' });
  assertEquals(ward.meta.guardStacks, 0);
  assertEquals(ward.meta.guardBrokenTurns, 4);
  assertEquals(effectKeys(world, caster).filter((key) => key === 'divine_shield').length, 1);
});

Deno.test("iron_flesh owns its defense, drag, and recoil identity", () => {
  const world = makeWorld();
  const caster = makeCaster(world, 5, 5);
  const attacker = makeEnemy(world, 5, 4);
  runSpellScript(world, caster, SPELL_DEFS.iron_flesh, {});

